<template><ThemePage><view class="spread-page"><text class="title">我的推广海报</text><text class="hint">选择商家模板，生成包含本人昵称、头像和真实推广二维码的海报。</text><view v-if="loading" role="status" class="message">正在读取本人推广资料与二维码…</view><view v-if="error" class="error" role="alert">{{error}}</view><button v-if="!auth.isLoggedIn" @tap="login">登录后生成海报</button><button v-else :disabled="loading" @tap="load">{{data?'重新读取推广资料':'生成推广海报'}}</button><template v-if="data&&code"><view class="identity"><image v-if="data.avatar" :src="data.avatar" mode="aspectFill"/><view><text>{{data.nickname}}</text><text class="hint">{{data.site_name}}</text></view></view><text class="subtitle">选择海报模板</text><scroll-view scroll-x class="template-strip"><view class="templates"><button v-for="(item,index) in data.spread" :key="index" class="choice" :class="{selected:selected===index}" :aria-label="'选择海报模板 '+(index+1)" @tap="choose(index)"><image :src="item.pic" mode="aspectFill"/><text>模板 {{index+1}}{{selected===index?' · 已选':''}}</text></button></view></scroll-view><SpreadPoster :owner-uid="ownerUid" :owner-version="ownerVersion" :template="data.spread[selected]?.pic||''" :avatar="data.avatar" :nickname="data.nickname" :site-name="data.site_name" :code="code" :active="visible"/></template><button class="finance" @tap="goFinance">查看分销记录与佣金</button><DiySuspendedNavigation/></view></ThemePage></template>
